using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace infrastructure.Data;

/// <summary>
/// Initialises the database (applies any pending migrations) and seeds it with
/// demo data for the portfolio build of this project.
///
/// IMPORTANT: this is the *public / portfolio* seed file. The catalog data
/// (categories, products, variants, images) is unchanged from the real store,
/// since it contains no personal information. Everything under "identity",
/// "shopping" and "sales" has been replaced with synthetic demo data — no
/// real names, emails, phone numbers, addresses, password hashes or OAuth
/// identifiers are present anywhere in this file.
///
/// A single demo account is seeded so reviewers can log in and try the app:
///   email:    demo.admin@example.com
///   password: Demo1234!
///
/// Snapshot contents:
/// - catalog.Categories: 20 rows   (unchanged, no personal data)
/// - catalog.Products: 232 rows    (unchanged, no personal data)
/// - catalog.Variants: 1355 rows   (unchanged, no personal data)
/// - catalog.Images: 960 rows      (unchanged, no personal data)
/// - identity.Users: 3 rows        (synthetic demo accounts)
/// - identity.Accounts: 3 rows     (demo password hash / fake OAuth id)
/// - identity.RefreshTokens: 1 row (single illustrative example only)
/// - identity.VerificationTokens: 1 row (single illustrative example only)
/// - shopping.Carts: 3 rows
/// - shopping.CartItems: 1 row
/// - sales.Purchases: 2 rows       (fake contact info)
/// - sales.PurchaseItems: 3 rows
/// - sales.Payments: 2 rows
///
/// The data is embedded as raw INSERT statements so that every id and
/// timestamp is preserved exactly, since the domain entities generate their
/// Id only inside protected constructors (Guid.Empty becomes Guid.NewGuid())
/// and all properties use private setters, which makes it impossible to
/// recreate specific identifiers and audit values through the domain
/// factory methods.
/// </summary>
public class ApplicationDbContextInitialiser(ILogger<ApplicationDbContextInitialiser> logger, AppDbContext context)
{
    /// <summary>
    /// Applies any pending migrations to the database.
    /// </summary>
    public async Task InitialiseAsync()
    {
        try
        {
            await context.Database.MigrateAsync();
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "An error occurred while initialising the database");
            throw;
        }
    }

    /// <summary>
    /// Seeds the database with the embedded demo snapshot.
    ///
    /// This is a one-time operation: it only runs against an empty database. On
    /// every subsequent start - or whenever the database already contains data -
    /// it does nothing. The presence of data in the seeded tables is used as the
    /// "already seeded" marker, so no extra table or flag is required.
    ///
    /// A transaction-scoped advisory lock makes the seed safe even if several
    /// application instances start at the same time: the first instance takes the
    /// lock and seeds, the others re-check inside the lock and skip.
    /// </summary>
    public async Task SeedAsync()
    {
        try
        {
            // Fast path: data already present -> nothing to do (seed runs only once).
            if (await AnyDataExistsAsync())
            {
                logger.LogInformation("Database already contains data - seeding skipped (seed runs only once, on an empty database)");
                return;
            }

            logger.LogInformation("Empty database detected - running one-time seed with {StatementCount} SQL statements", SeedStatements.Length);

            await using var transaction = await context.Database.BeginTransactionAsync();

            // Serialise concurrent starts: only the first instance gets past this lock.
            await context.Database.ExecuteSqlRawAsync("SELECT pg_advisory_xact_lock(657201);");

            // Re-check inside the lock: another instance may have seeded meanwhile.
            if (await AnyDataExistsAsync())
            {
                logger.LogInformation("Database was already seeded by another instance - seeding skipped");
                await transaction.RollbackAsync();
                return;
            }

            foreach (string statement in SeedStatements)
                await context.Database.ExecuteSqlRawAsync(statement);

            await transaction.CommitAsync();

            logger.LogInformation("Database seeded successfully - one-time seed completed");
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "An error occurred while seeding the database");
            throw;
        }
    }

    /// <summary>
    /// Returns true when any of the seeded tables already contains rows.
    /// </summary>
    private async Task<bool> AnyDataExistsAsync()
    {
        return await context.Database
            .SqlQuery<bool>($"""
                SELECT (EXISTS (SELECT 1 FROM "catalog"."Categories") OR EXISTS (SELECT 1 FROM "catalog"."Products") OR EXISTS (SELECT 1 FROM "catalog"."Variants") OR EXISTS (SELECT 1 FROM "catalog"."Images") OR EXISTS (SELECT 1 FROM "identity"."Users") OR EXISTS (SELECT 1 FROM "identity"."Accounts") OR EXISTS (SELECT 1 FROM "identity"."RefreshTokens") OR EXISTS (SELECT 1 FROM "identity"."VerificationTokens") OR EXISTS (SELECT 1 FROM "shopping"."Carts") OR EXISTS (SELECT 1 FROM "shopping"."CartItems") OR EXISTS (SELECT 1 FROM "sales"."Purchases") OR EXISTS (SELECT 1 FROM "sales"."PurchaseItems") OR EXISTS (SELECT 1 FROM "sales"."Payments")) AS "Value"
                """)
            .SingleAsync();
    }

